import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        final Solution.Registry registry = Solution.createRegistry();
        if (registry == null) throw new AssertionError("registry must not be null");

        Solution.addMember(registry, 20L, " Bob ", " Yellow ");
        Solution.addMember(registry, 5L, "alice", " Zephyr");
        Solution.addMember(registry, 10L, "ALICE", "yellow");
        Solution.addMember(registry, 30L, "Carol", "Yellow");

        assertIds(Solution.search(registry, null, null), 5L, 10L, 20L, 30L);
        assertIds(Solution.search(registry, "   ", ""), 5L, 10L, 20L, 30L);
        assertIds(Solution.search(registry, " Alice ", null), 5L, 10L);
        assertIds(Solution.search(registry, null, " YELLOW "), 10L, 20L, 30L);
        assertIds(Solution.search(registry, "alice", "yellow"), 10L);
        assertIds(Solution.search(registry, "nobody", null));

        Solution.Member member = Solution.search(registry, "bob", "yellow").get(0);
        assertEquals(20L, member.id());
        assertEquals("Bob", member.givenName());
        assertEquals("Yellow", member.familyName());

        final List<Solution.Member> searchSnapshot = Solution.search(registry, null, null);
        expectUnsupported(new Runnable() {
            public void run() { searchSnapshot.clear(); }
        });
        Solution.addMember(registry, 40L, "Dora", "North");
        assertIds(searchSnapshot, 5L, 10L, 20L, 30L);

        assertTrue(!Solution.subscribe(registry, 5L, 5L), "self-subscription must fail");
        assertTrue(Solution.subscribe(registry, 5L, 30L), "new subscription");
        assertTrue(Solution.subscribe(registry, 5L, 10L), "new subscription");
        assertTrue(Solution.subscribe(registry, 5L, 20L), "new subscription");
        assertTrue(!Solution.subscribe(registry, 5L, 10L), "duplicate subscription");
        final List<Solution.Member> subscriptionSnapshot = Solution.subscriptions(registry, 5L);
        assertIds(subscriptionSnapshot, 10L, 20L, 30L);
        expectUnsupported(new Runnable() {
            public void run() { subscriptionSnapshot.remove(0); }
        });
        assertTrue(Solution.unsubscribe(registry, 5L, 20L), "existing unsubscribe");
        assertTrue(!Solution.unsubscribe(registry, 5L, 20L), "missing unsubscribe");
        assertIds(subscriptionSnapshot, 10L, 20L, 30L);
        assertIds(Solution.subscriptions(registry, 5L), 10L, 30L);

        expectIllegalArgument(new Runnable() {
            public void run() { Solution.addMember(registry, -1L, "A", "B"); }
        });
        expectIllegalArgument(new Runnable() {
            public void run() { Solution.addMember(registry, 5L, "Other", "Person"); }
        });
        expectIllegalArgument(new Runnable() {
            public void run() { Solution.addMember(registry, 50L, null, "Person"); }
        });
        expectIllegalArgument(new Runnable() {
            public void run() { Solution.addMember(registry, 51L, " ", "Person"); }
        });
        expectIllegalArgument(new Runnable() {
            public void run() { Solution.addMember(registry, 52L, "Person", " "); }
        });
        expectIllegalArgument(new Runnable() {
            public void run() { Solution.subscribe(registry, 999L, 5L); }
        });
        expectIllegalArgument(new Runnable() {
            public void run() { Solution.unsubscribe(registry, 5L, 999L); }
        });
        expectNullPointer(new Runnable() {
            public void run() { Solution.addMember(null, 1L, "A", "B"); }
        });
        expectNullPointer(new Runnable() {
            public void run() { Solution.search(null, null, null); }
        });
    }

    private static void assertIds(List<Solution.Member> members, long... expected) {
        assertEquals(expected.length, members.size());
        for (int i = 0; i < expected.length; i++) assertEquals(expected[i], members.get(i).id());
    }

    private static void expectIllegalArgument(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }

    private static void expectNullPointer(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected NullPointerException");
        } catch (NullPointerException expected) {
        }
    }

    private static void expectUnsupported(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void assertEquals(Object expected, Object actual) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError("expected " + expected + " but got " + actual);
        }
    }
}

